### Background and motivation

API proposal for: https://github.com/dotnet/runtime/issues/73500

In .NET 7 we've added Int128/UInt128 support. This API proposal is adding APIs needed to make source-gen fast path work with those types and making it easier for users to use these types directly from JsonReader/Writer/JsonNode and write their own converter.

### API Proposal

```csharp
#if NET7_0_OR_GREATER // because Int128/UInt128 didn't exist before
namespace System.Text.Json
{
    public ref partial struct Utf8JsonReader
    {
        public System.Int128 GetInt128() { throw null; }
        public bool TryGetInt128(out System.Int128 value) { throw null; }
        [System.CLSCompliantAttribute(false)]
        public System.UInt128 GetUInt128() { throw null; }
        [System.CLSCompliantAttribute(false)]
        public bool TryGetUInt128(out System.UInt128 value) { throw null; }
    }
    public sealed partial class Utf8JsonWriter : System.IAsyncDisposable, System.IDisposable
    {
        public void WriteNumberValue(System.Int128 value) { }
        [System.CLSCompliantAttribute(false)]
        public void WriteNumberValue(System.UInt128 value) { }
    }
    public readonly partial struct JsonElement
    {
        public System.Int128 GetInt128() { throw null; }
        public bool TryGetInt128(out System.Int128 value) { throw null; }
        [System.CLSCompliantAttribute(false)]
        public System.UInt128 GetUInt128() { throw null; }
        [System.CLSCompliantAttribute(false)]
        public bool TryGetUInt128(out System.UInt128 value) { throw null; }
    }
}
namespace System.Text.Json.Nodes
{
    public abstract partial class JsonNode
    {
        public static explicit operator System.Int128(System.Text.Json.Nodes.JsonNode value) { throw null; }
        public static explicit operator System.Int128?(System.Text.Json.Nodes.JsonNode? value) { throw null; }
        [System.CLSCompliantAttribute(false)]
        public static explicit operator System.UInt128(System.Text.Json.Nodes.JsonNode value) { throw null; }
        [System.CLSCompliantAttribute(false)]
        public static explicit operator System.UInt128?(System.Text.Json.Nodes.JsonNode? value) { throw null; }
        public static implicit operator JsonNode(System.Int128 value) { throw null; }
        public static implicit operator JsonNode?(System.Int128? value) { throw null; }
        [System.CLSCompliantAttribute(false)]
        public static implicit operator JsonNode(System.UInt128 value) { throw null; }
        [System.CLSCompliantAttribute(false)]
        public static implicit operator JsonNode?(System.UInt128? value) { throw null; }
    }
    public abstract partial class JsonValue
    {
        public static System.Text.Json.Nodes.JsonValue Create(System.Int128 value, System.Text.Json.Nodes.JsonNodeOptions? options = null) { throw null; }
        public static System.Text.Json.Nodes.JsonValue? Create(System.Int128? value, System.Text.Json.Nodes.JsonNodeOptions? options = null) { throw null; }
        [System.CLSCompliantAttribute(false)]
        public static System.Text.Json.Nodes.JsonValue Create(System.UInt128 value, System.Text.Json.Nodes.JsonNodeOptions? options = null) { throw null; }
        [System.CLSCompliantAttribute(false)]
        public static System.Text.Json.Nodes.JsonValue? Create(System.UInt128? value, System.Text.Json.Nodes.JsonNodeOptions? options = null) { throw null; }
    }
}
namespace System.Text.Json.Serialization.Metadata
{
    public static partial class JsonMetadataServices
    {
        public static System.Text.Json.Serialization.JsonConverter<System.Int128> Int128Converter { get { throw null; } }
        [System.CLSCompliantAttribute(false)]
        public static System.Text.Json.Serialization.JsonConverter<System.UInt128> UInt128Converter { get { throw null; } }
    }
}
#endif // NET7_0_OR_GREATER

// Added to fix source breaking change in source-gen and user code caused by adding new UInt128/Int128 overloads
// where some overloads became ambiguous (i.e. passing in byte/ushort value to WriteNumber overloads)
// This is per recommendation from @jaredpar and @tannergooding in https://github.com/dotnet/runtime/issues/74001
// they're matching existing overloads for (u)long, (u)int
namespace System.Text.Json
{
    public sealed partial class Utf8JsonWriter
    {
        [System.CLSCompliantAttribute(false)]
        public void WriteNumber(System.ReadOnlySpan<byte> utf8PropertyName, sbyte value) { }
        public void WriteNumber(System.ReadOnlySpan<byte> utf8PropertyName, short value) { }

        public void WriteNumber(System.ReadOnlySpan<byte> utf8PropertyName, byte value) { }
        [System.CLSCompliantAttribute(false)]
        public void WriteNumber(System.ReadOnlySpan<byte> utf8PropertyName, ushort value) { }

        [System.CLSCompliantAttribute(false)]
        public void WriteNumber(System.ReadOnlySpan<char> propertyName, sbyte value) { }
        public void WriteNumber(System.ReadOnlySpan<char> propertyName, short value) { }

        public void WriteNumber(System.ReadOnlySpan<char> propertyName, byte value) { }
        [System.CLSCompliantAttribute(false)]
        public void WriteNumber(System.ReadOnlySpan<char> propertyName, ushort value) { }

        [System.CLSCompliantAttribute(false)]
        public void WriteNumber(string propertyName, sbyte value) { }
        public void WriteNumber(string propertyName, short value) { }

        public void WriteNumber(string propertyName, byte value) { }
        [System.CLSCompliantAttribute(false)]
        public void WriteNumber(string propertyName, ushort value) { }

        [System.CLSCompliantAttribute(false)]
        public void WriteNumber(System.Text.Json.JsonEncodedText propertyName, sbyte value) { }
        public void WriteNumber(System.Text.Json.JsonEncodedText propertyName, short value) { }

        public void WriteNumber(System.Text.Json.JsonEncodedText propertyName, byte value) { }
        [System.CLSCompliantAttribute(false)]
        public void WriteNumber(System.Text.Json.JsonEncodedText propertyName, ushort value) { }

        [System.CLSCompliantAttribute(false)]
        public void WriteNumberValue(sbyte value) { }
        public void WriteNumberValue(short value) { }

        public void WriteNumberValue(byte value) { }
        [System.CLSCompliantAttribute(false)]
        public void WriteNumberValue(ushort value) { }
    }
}
```


### API Usage

```csharp
Utf8JsonReader reader = ...;
Int128 number = reader.GetInt128();

var obj = JsonSerializer.Deserialize<SomeClassWithInt128>(someObjectWithInt128);

// and similar for other overloads
```


### Alternative Designs

_No response_

### Risks

No known risks, adding matching APIs similar to long/ulong

